"use client"

import { useEffect, useRef, useState, type CSSProperties, type ReactNode, type RefObject } from "react"

import { usePrefersReducedMotion } from "@/hooks/use-prefers-reduced-motion"
import { cn } from "@/lib/cn"

import { mountGlLoop, type GlContext, type GlFrame, type GlLoopHandle } from "./gl/gl-loop"

/** original implementation. A glass body refracts the backdrop behind it, with dispersion. */

export interface GlassRefractHeroProps {
  speed?: number
  intensity?: number
  size?: number
  src?: string
  className?: string
  children?: ReactNode
}

type Rgb = [number, number, number]

interface Tuning {
  speed: number
  intensity: number
  size: number
}

interface Compiled {
  program: WebGLProgram
  loc: (name: string) => WebGLUniformLocation | null
}

interface GlassSession {
  draw: (frame: GlFrame) => void
  dispose: () => void
}

export function clampGlassSpeed(speed: number): number {
  if (!Number.isFinite(speed)) return 1
  return Math.min(2.5, Math.max(0.25, speed))
}

export function clampGlassIntensity(intensity: number): number {
  if (!Number.isFinite(intensity)) return 0.45
  return Math.min(1, Math.max(0, intensity))
}

export function clampGlassSize(size: number): number {
  if (!Number.isFinite(size)) return 180
  return Math.min(320, Math.max(72, size))
}

/** 像素直径在这块 CSS 盒子上的 UV 半径。宽高为 0 时按 1。 */
export function glassRadiusUv(size: number, cssWidth: number, cssHeight: number): { x: number; y: number } {
  const diameter = clampGlassSize(size)
  const width = cssWidth > 0 && Number.isFinite(cssWidth) ? cssWidth : 1
  const height = cssHeight > 0 && Number.isFinite(cssHeight) ? cssHeight : 1
  return { x: diameter / 2 / width, y: diameter / 2 / height }
}

/** 相对画面中心的 UV 偏移。time 为秒，speed 先夹到 0.25–2.5。 */
export function glassDrift(time: number, speed: number): { x: number; y: number } {
  const seconds = Number.isFinite(time) ? time : 0
  const angle = seconds * clampGlassSpeed(speed)
  return { x: Math.sin(angle) * 0.08, y: Math.cos(angle) * 0.05 }
}

/** 镜片边缘的折射位移，单位 UV。 */
export function glassBend(intensity: number): number {
  return clampGlassIntensity(intensity) * 0.125
}

/** 红蓝通道分开的距离，单位 UV。 */
export function glassShift(intensity: number): number {
  return clampGlassIntensity(intensity) * 0.03125
}

/** 空地址或加载失败时留在程序化后景。 */
export function glassBackdrop(src: string | undefined, failed: boolean): "procedural" | "image" {
  if (failed) return "procedural"
  if (typeof src !== "string" || src.trim().length === 0) return "procedural"
  return "image"
}

function parseCssColor(input: string): Rgb | null {
  const text = input.trim()
  const hex = /^#([\da-f]{3}|[\da-f]{6})$/i.exec(text)
  const body = hex?.[1]
  if (body) {
    const full = body.length === 3 ? body.split("").map((char) => char + char).join("") : body
    const value = Number.parseInt(full, 16)
    return [((value >> 16) & 255) / 255, ((value >> 8) & 255) / 255, (value & 255) / 255]
  }
  const rgb = /^rgba?\(\s*([\d.]+)[,\s]+([\d.]+)[,\s]+([\d.]+)/i.exec(text)
  if (!rgb?.[1] || !rgb[2] || !rgb[3]) return null
  return [Number(rgb[1]) / 255, Number(rgb[2]) / 255, Number(rgb[3]) / 255]
}

const colorCache = new Map<string, Rgb>()

function resolveOnHost(host: HTMLElement, raw: string): Rgb | null {
  const previous = host.style.color
  host.style.color = raw
  try {
    return parseCssColor(getComputedStyle(host).color)
  } finally {
    host.style.color = previous
  }
}

function themeChannel(host: HTMLElement, style: CSSStyleDeclaration, token: string, fallback: Rgb): Rgb {
  const raw = style.getPropertyValue(token).trim()
  if (!raw) return fallback
  const hit = colorCache.get(raw)
  if (hit) return hit
  const resolved = parseCssColor(raw) ?? resolveOnHost(host, raw) ?? fallback
  colorCache.set(raw, resolved)
  return resolved
}

function backdropColor(host: HTMLElement, style: CSSStyleDeclaration): Rgb {
  if (style.getPropertyValue("--background").trim()) {
    return themeChannel(host, style, "--background", [0.96, 0.95, 0.93])
  }
  return parseCssColor(style.backgroundColor) ?? [0.96, 0.95, 0.93]
}

function glassVertex(webgl2: boolean) {
  const head = webgl2 ? "#version 300 es\nin vec2 a;\nout vec2 v;\n" : "attribute vec2 a;\nvarying vec2 v;\n"
  return `${head}void main(){v=a*0.5+0.5;gl_Position=vec4(a,0.0,1.0);}`
}

function glassFragment(webgl2: boolean) {
  const head = webgl2
    ? "#version 300 es\nprecision highp float;\nin vec2 v;\nout vec4 frag;\n#define TEX texture\n#define WRITE frag\n"
    : "precision mediump float;\nvarying vec2 v;\n#define TEX texture2D\n#define WRITE gl_FragColor\n"
  return `${head}
uniform vec2 uCenter;
uniform vec2 uRadius;
uniform float uBend;
uniform float uShift;
uniform float uImage;
uniform vec3 uBg;
uniform vec3 uInk;
uniform vec3 uWarm;
uniform sampler2D uTex;
vec3 field(vec2 uv) {
  vec2 p = clamp(uv, 0.0, 1.0);
  float bands = 0.5 + 0.5 * sin(p.x * 10.0 + p.y * 3.0);
  float bloom = smoothstep(0.72, 0.0, length(p - vec2(0.28, 0.7)));
  vec3 color = mix(uBg, uInk, bands * 0.62);
  return mix(color, uWarm, bloom * 0.7);
}
vec3 sampleAt(vec2 uv) {
  vec2 clamped = clamp(uv, 0.0, 1.0);
  vec3 drawn = field(clamped);
  vec2 tex = vec2(clamped.x, 1.0 - clamped.y);
  return mix(drawn, TEX(uTex, tex).rgb, clamp(uImage, 0.0, 1.0));
}
void main() {
  vec2 radius = max(uRadius, vec2(0.0008));
  vec2 local = (v - uCenter) / radius;
  float dist = length(local);
  float mask = 1.0 - smoothstep(0.96, 1.04, dist);
  vec2 dir = dist > 0.0001 ? local / dist : vec2(0.0);
  float rim = clamp(dist, 0.0, 1.0);
  vec2 bend = dir * rim * uBend;
  float split = rim * uShift;
  vec3 bent;
  bent.r = sampleAt(v - bend - dir * split).r;
  bent.g = sampleAt(v - bend).g;
  bent.b = sampleAt(v - bend + dir * split).b;
  float edge = smoothstep(0.62, 1.0, dist) * mask;
  bent = mix(bent, vec3(1.0), edge * 0.28);
  WRITE = vec4(mix(sampleAt(v), bent, mask), 1.0);
}`
}

function shaderOf(gl: GlContext, type: number, source: string) {
  const item = gl.createShader(type)
  if (!item) return null
  gl.shaderSource(item, source)
  gl.compileShader(item)
  if (!gl.getShaderParameter(item, gl.COMPILE_STATUS)) {
    gl.deleteShader(item)
    return null
  }
  return item
}

function compile(gl: GlContext, vertex: string, fragment: string): Compiled | null {
  const program = gl.createProgram()
  if (!program) return null
  const vs = shaderOf(gl, gl.VERTEX_SHADER, vertex)
  const fs = shaderOf(gl, gl.FRAGMENT_SHADER, fragment)
  if (!vs || !fs) {
    if (vs) gl.deleteShader(vs)
    if (fs) gl.deleteShader(fs)
    gl.deleteProgram(program)
    return null
  }
  gl.attachShader(program, vs)
  gl.attachShader(program, fs)
  gl.bindAttribLocation(program, 0, "a")
  gl.linkProgram(program)
  gl.deleteShader(vs)
  gl.deleteShader(fs)
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    gl.deleteProgram(program)
    return null
  }
  return { program, loc: (name) => gl.getUniformLocation(program, name) }
}

function makeTexture(gl: GlContext): WebGLTexture | null {
  const texture = gl.createTexture()
  if (!texture) return null
  gl.bindTexture(gl.TEXTURE_2D, texture)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE)
  gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, 1, 1, 0, gl.RGBA, gl.UNSIGNED_BYTE, new Uint8Array([0, 0, 0, 255]))
  gl.bindTexture(gl.TEXTURE_2D, null)
  return texture
}

function uploadImage(gl: GlContext, texture: WebGLTexture, image: HTMLImageElement): boolean {
  if (image.naturalWidth <= 0) return false
  try {
    gl.bindTexture(gl.TEXTURE_2D, texture)
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR)
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR)
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE)
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE)
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, image)
    return true
  } catch {
    return false
  }
}

function startSession(
  loop: GlLoopHandle,
  host: HTMLElement,
  tuning: RefObject<Tuning>,
  imageRef: RefObject<HTMLImageElement | null>,
): GlassSession | null {
  const gl = loop.gl
  const webgl2 = typeof (gl as WebGL2RenderingContext).drawBuffers === "function"
  const compiled = compile(gl, glassVertex(webgl2), glassFragment(webgl2))
  const texture = makeTexture(gl)
  if (!compiled || !texture) {
    if (compiled) gl.deleteProgram(compiled.program)
    if (texture) gl.deleteTexture(texture)
    return null
  }
  let uploaded: HTMLImageElement | null = null
  let usable = false
  return {
    draw(frame) {
      const current = tuning.current
      const speed = clampGlassSpeed(current?.speed ?? 1)
      const intensity = clampGlassIntensity(current?.intensity ?? 0.45)
      const size = clampGlassSize(current?.size ?? 180)
      const image = imageRef.current
      if (image !== uploaded) {
        uploaded = image
        usable = image ? uploadImage(gl, texture, image) : false
      }
      const drift = glassDrift(frame.time, speed)
      const radius = glassRadiusUv(size, frame.size.cssWidth, frame.size.cssHeight)
      const style = getComputedStyle(host)
      const bg = backdropColor(host, style)
      const ink = themeChannel(host, style, "--primary", [0.28, 0.33, 0.62])
      const warm = themeChannel(host, style, "--chart-2", [0.55, 0.36, 0.18])
      gl.bindFramebuffer(gl.FRAMEBUFFER, null)
      gl.viewport(0, 0, frame.size.width, frame.size.height)
      gl.disable(gl.BLEND)
      gl.useProgram(compiled.program)
      gl.activeTexture(gl.TEXTURE0)
      gl.bindTexture(gl.TEXTURE_2D, texture)
      gl.uniform1i(compiled.loc("uTex"), 0)
      gl.uniform2f(compiled.loc("uCenter"), 0.5 + drift.x, 0.5 + drift.y)
      gl.uniform2f(compiled.loc("uRadius"), radius.x, radius.y)
      gl.uniform1f(compiled.loc("uBend"), glassBend(intensity))
      gl.uniform1f(compiled.loc("uShift"), glassShift(intensity))
      gl.uniform1f(compiled.loc("uImage"), usable ? 1 : 0)
      gl.uniform3f(compiled.loc("uBg"), bg[0], bg[1], bg[2])
      gl.uniform3f(compiled.loc("uInk"), ink[0], ink[1], ink[2])
      gl.uniform3f(compiled.loc("uWarm"), warm[0], warm[1], warm[2])
      loop.draw()
    },
    dispose() {
      gl.deleteProgram(compiled.program)
      gl.deleteTexture(texture)
    },
  }
}

function cssUrl(src: string) {
  return `url("${src.replace(/["'\\()\n\r]/g, "")}")`
}

function stillStyle(backdrop: "procedural" | "image", src: string | undefined): CSSProperties {
  if (backdrop === "image" && src?.trim()) {
    return {
      backgroundColor: "var(--background)",
      backgroundImage: cssUrl(src.trim()),
      backgroundPosition: "center",
      backgroundSize: "cover",
    }
  }
  return {
    backgroundColor: "var(--background)",
    backgroundImage: [
      "radial-gradient(42% 48% at 28% 70%, color-mix(in oklab, var(--primary) 55%, transparent), transparent 70%)",
      "radial-gradient(34% 40% at 74% 28%, color-mix(in oklab, var(--chart-2) 50%, transparent), transparent 72%)",
      "linear-gradient(165deg, var(--background), var(--muted))",
    ].join(", "),
  }
}

function bodyStyle(size: number): CSSProperties {
  const px = `${clampGlassSize(size)}px`
  return {
    position: "absolute",
    left: "50%",
    top: "46%",
    width: px,
    height: px,
    transform: "translate(-50%, -50%)",
    borderRadius: "9999px",
    background:
      "radial-gradient(circle at 34% 30%, color-mix(in oklab, white 72%, transparent), color-mix(in oklab, var(--primary) 16%, transparent) 46%, transparent 70%)",
    boxShadow:
      "inset 0 0 0 1px color-mix(in oklab, white 70%, transparent), inset 0 0 28px color-mix(in oklab, var(--primary) 22%, transparent)",
  }
}

function GlassRefractHero({
  speed = 1,
  intensity = 0.45,
  size = 180,
  src,
  className,
  children,
}: GlassRefractHeroProps) {
  const reduced = usePrefersReducedMotion()
  const hostRef = useRef<HTMLDivElement>(null)
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const imageRef = useRef<HTMLImageElement | null>(null)
  const tuningRef = useRef<Tuning>({ speed, intensity, size })
  const address = src?.trim() ?? ""
  const [loadedSrc, setLoadedSrc] = useState<string | null>(null)
  const [tracked, setTracked] = useState(address)
  const [blocked, setBlocked] = useState(false)
  if (address !== tracked) {
    setTracked(address)
    setLoadedSrc(null)
  }
  const backdrop = glassBackdrop(address, loadedSrc !== address)
  const still = reduced || blocked

  useEffect(() => {
    tuningRef.current = { speed, intensity, size }
  }, [speed, intensity, size])

  useEffect(() => {
    imageRef.current = null
    if (glassBackdrop(address, false) !== "image") return
    let gone = false
    const image = new Image()
    if (/^https?:\/\//i.test(address)) image.crossOrigin = "anonymous"
    image.onload = () => {
      if (gone) return
      imageRef.current = image
      setLoadedSrc(address)
    }
    image.onerror = () => {
      if (gone) return
      imageRef.current = null
      setLoadedSrc(null)
    }
    image.src = address
    return () => {
      gone = true
    }
  }, [address])

  useEffect(() => {
    if (reduced) return
    const canvas = canvasRef.current
    const host = hostRef.current
    if (!canvas || !host) return
    let gone = false
    let session: GlassSession | null = null
    let loop: GlLoopHandle | null = null
    loop = mountGlLoop(canvas, {
      host,
      frame: (frame) => {
        if (gone || !loop) return
        if (!session) {
          session = startSession(loop, host, tuningRef, imageRef)
          if (!session) {
            gone = true
            loop.dispose()
            setBlocked(true)
            return
          }
        }
        session.draw(frame)
      },
    })
    if (!loop) {
      setBlocked(true)
      return
    }
    return () => {
      gone = true
      session?.dispose()
      loop?.dispose()
    }
  }, [reduced])

  return (
    <div
      ref={hostRef}
      data-slot="glass-refract-hero"
      data-state={still ? "still" : "live"}
      data-backdrop={backdrop}
      className={cn("relative h-96 w-full overflow-hidden rounded-xl bg-background text-foreground", className)}
    >
      {still ? (
        <div data-fallback="still" aria-hidden className="pointer-events-none absolute inset-0" style={stillStyle(backdrop, src)}>
          <div data-glass="body" style={bodyStyle(size)} />
        </div>
      ) : (
        <canvas ref={canvasRef} aria-hidden className="pointer-events-none absolute inset-0 h-full w-full" />
      )}
      <div className="relative z-10 p-6">{children}</div>
    </div>
  )
}

export { GlassRefractHero }

"use client"

/** 设备像素比上限 1.5。0 或空值按 1。 */
export function cappedDpr(dpr: number): number {
  return Math.min(dpr || 1, 1.5)
}

/** 离开视口或页面隐藏时，连续帧停住。 */
export function shouldDrawFrame(inView: boolean, pageVisible: boolean): boolean {
  return inView && pageVisible
}

export type GlContext = WebGL2RenderingContext | WebGLRenderingContext

export interface GlSize {
  cssWidth: number
  cssHeight: number
  width: number
  height: number
  dpr: number
}

export interface GlFrame {
  gl: GlContext
  time: number
  dt: number
  size: GlSize
}

/** 浮点颜色附件是否可渲染。half 为真时用半精度。 */
export interface FloatSupport {
  renderable: boolean
  half: boolean
}

export interface GlTarget {
  framebuffer: WebGLFramebuffer
  texture: WebGLTexture
  width: number
  height: number
}

export interface GlPair {
  read: GlTarget
  write: GlTarget
  swap: () => void
  resize: (width: number, height: number) => void
  dispose: () => void
}

export interface GlLoopHandle {
  gl: GlContext
  floatSupport: FloatSupport
  dispose: () => void
  size: () => GlSize
  createPair: (width: number, height: number) => GlPair | null
  /** 全屏三角形。顶点属性 location 0，名字是 a。 */
  draw: () => void
}

interface TexFormat {
  internal: number
  format: number
  type: number
}

function isGlContext(value: unknown): value is GlContext {
  if (typeof value !== "object" || value === null) return false
  const record = value as { createShader?: unknown; drawArrays?: unknown; getExtension?: unknown }
  return (
    typeof record.createShader === "function" &&
    typeof record.drawArrays === "function" &&
    typeof record.getExtension === "function"
  )
}

function isWebGL2(gl: GlContext): gl is WebGL2RenderingContext {
  return typeof (gl as WebGL2RenderingContext).drawBuffers === "function"
}

function obtainGl(canvas: HTMLCanvasElement): GlContext | null {
  const attrs: WebGLContextAttributes = {
    alpha: true,
    antialias: false,
    depth: false,
    stencil: false,
    premultipliedAlpha: false,
  }
  try {
    const gl2 = canvas.getContext("webgl2", attrs)
    if (isGlContext(gl2)) return gl2
    const gl = canvas.getContext("webgl", attrs)
    if (isGlContext(gl)) return gl
    return null
  } catch {
    return null
  }
}

function byteFormat(gl: GlContext): TexFormat {
  return { internal: gl.RGBA, format: gl.RGBA, type: gl.UNSIGNED_BYTE }
}

function floatFormat(gl: GlContext, support: FloatSupport): TexFormat {
  if (!support.renderable) return byteFormat(gl)
  if (isWebGL2(gl)) {
    if (support.half) return { internal: gl.RGBA16F, format: gl.RGBA, type: gl.HALF_FLOAT }
    return { internal: gl.RGBA32F, format: gl.RGBA, type: gl.FLOAT }
  }
  return { internal: gl.RGBA, format: gl.RGBA, type: gl.FLOAT }
}

function fillTexture(gl: GlContext, texture: WebGLTexture, width: number, height: number, format: TexFormat) {
  gl.bindTexture(gl.TEXTURE_2D, texture)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE)
  gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE)
  gl.texImage2D(gl.TEXTURE_2D, 0, format.internal, width, height, 0, format.format, format.type, null)
}

function attach(gl: GlContext, framebuffer: WebGLFramebuffer, texture: WebGLTexture) {
  gl.bindFramebuffer(gl.FRAMEBUFFER, framebuffer)
  gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, texture, 0)
  return gl.checkFramebufferStatus(gl.FRAMEBUFFER) === gl.FRAMEBUFFER_COMPLETE
}

function probeFormat(gl: GlContext, format: TexFormat): boolean {
  const texture = gl.createTexture()
  const framebuffer = gl.createFramebuffer()
  if (!texture || !framebuffer) {
    if (texture) gl.deleteTexture(texture)
    if (framebuffer) gl.deleteFramebuffer(framebuffer)
    return false
  }
  fillTexture(gl, texture, 1, 1, format)
  const ok = attach(gl, framebuffer, texture)
  gl.bindFramebuffer(gl.FRAMEBUFFER, null)
  gl.bindTexture(gl.TEXTURE_2D, null)
  gl.deleteTexture(texture)
  gl.deleteFramebuffer(framebuffer)
  return ok
}

function probeFloat(gl: GlContext): FloatSupport {
  if (!isWebGL2(gl)) {
    const textureFloat = gl.getExtension("OES_texture_float")
    const colorBuffer = gl.getExtension("WEBGL_color_buffer_float")
    if (!textureFloat || !colorBuffer) return { renderable: false, half: false }
    return { renderable: probeFormat(gl, { internal: gl.RGBA, format: gl.RGBA, type: gl.FLOAT }), half: false }
  }
  gl.getExtension("EXT_color_buffer_float")
  if (probeFormat(gl, { internal: gl.RGBA16F, format: gl.RGBA, type: gl.HALF_FLOAT })) {
    return { renderable: true, half: true }
  }
  if (probeFormat(gl, { internal: gl.RGBA32F, format: gl.RGBA, type: gl.FLOAT })) {
    return { renderable: true, half: false }
  }
  return { renderable: false, half: false }
}

function destroyTarget(gl: GlContext, target: GlTarget) {
  gl.deleteFramebuffer(target.framebuffer)
  gl.deleteTexture(target.texture)
}

function createTarget(gl: GlContext, width: number, height: number, support: FloatSupport): GlTarget | null {
  const texture = gl.createTexture()
  const framebuffer = gl.createFramebuffer()
  if (!texture || !framebuffer) {
    if (texture) gl.deleteTexture(texture)
    if (framebuffer) gl.deleteFramebuffer(framebuffer)
    return null
  }
  const w = Math.max(1, Math.floor(width))
  const h = Math.max(1, Math.floor(height))
  const preferred = floatFormat(gl, support)
  fillTexture(gl, texture, w, h, preferred)
  let ok = attach(gl, framebuffer, texture)
  if (!ok && preferred.type !== gl.UNSIGNED_BYTE) {
    fillTexture(gl, texture, w, h, byteFormat(gl))
    ok = attach(gl, framebuffer, texture)
  }
  gl.bindFramebuffer(gl.FRAMEBUFFER, null)
  gl.bindTexture(gl.TEXTURE_2D, null)
  if (!ok) {
    gl.deleteTexture(texture)
    gl.deleteFramebuffer(framebuffer)
    return null
  }
  return { framebuffer, texture, width: w, height: h }
}

function resizeTarget(gl: GlContext, target: GlTarget, width: number, height: number, support: FloatSupport) {
  const w = Math.max(1, Math.floor(width))
  const h = Math.max(1, Math.floor(height))
  if (target.width === w && target.height === h) return
  const preferred = floatFormat(gl, support)
  fillTexture(gl, target.texture, w, h, preferred)
  let ok = attach(gl, target.framebuffer, target.texture)
  if (!ok && preferred.type !== gl.UNSIGNED_BYTE) {
    fillTexture(gl, target.texture, w, h, byteFormat(gl))
    ok = attach(gl, target.framebuffer, target.texture)
  }
  gl.bindFramebuffer(gl.FRAMEBUFFER, null)
  gl.bindTexture(gl.TEXTURE_2D, null)
  if (ok) {
    target.width = w
    target.height = h
  }
}

function createPair(gl: GlContext, width: number, height: number, support: FloatSupport): GlPair | null {
  const first = createTarget(gl, width, height, support)
  const second = createTarget(gl, width, height, support)
  if (!first || !second) {
    if (first) destroyTarget(gl, first)
    if (second) destroyTarget(gl, second)
    return null
  }
  const pair: GlPair = {
    read: first,
    write: second,
    swap() {
      const next = pair.read
      pair.read = pair.write
      pair.write = next
    },
    resize(nextWidth, nextHeight) {
      resizeTarget(gl, pair.read, nextWidth, nextHeight, support)
      resizeTarget(gl, pair.write, nextWidth, nextHeight, support)
    },
    dispose() {
      destroyTarget(gl, pair.read)
      destroyTarget(gl, pair.write)
    },
  }
  return pair
}

function measureOf(host: HTMLElement, canvas: HTMLCanvasElement): GlSize {
  const rect = host.getBoundingClientRect()
  const cssWidth = Math.max(1, rect.width || host.clientWidth || 1)
  const cssHeight = Math.max(1, rect.height || host.clientHeight || 1)
  const raw = typeof window === "undefined" ? 1 : window.devicePixelRatio
  const dpr = cappedDpr(typeof raw === "number" ? raw : 1)
  const width = Math.max(1, Math.round(cssWidth * dpr))
  const height = Math.max(1, Math.round(cssHeight * dpr))
  if (canvas.width !== width) canvas.width = width
  if (canvas.height !== height) canvas.height = height
  return { cssWidth, cssHeight, width, height, dpr }
}

function createTriangle(gl: GlContext): WebGLBuffer | null {
  const buffer = gl.createBuffer()
  if (!buffer) return null
  gl.bindBuffer(gl.ARRAY_BUFFER, buffer)
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW)
  gl.bindBuffer(gl.ARRAY_BUFFER, null)
  return buffer
}

function releaseContext(gl: GlContext) {
  gl.getExtension("WEBGL_lose_context")?.loseContext()
}

/**
 * 多 pass 效果共用的原始 WebGL 循环。只管生命周期：成对 framebuffer、全屏三角形、
 * 浮点纹理探测、像素比上限、尺寸、离屏暂停、卸载时释放 context。
 * getContext 拿不到时返回 null，不抛。
 */
export function mountGlLoop(
  canvas: HTMLCanvasElement,
  options: {
    host: HTMLElement
    frame: (frame: GlFrame) => void
  },
): GlLoopHandle | null {
  const gl = obtainGl(canvas)
  if (!gl) return null
  const triangle = createTriangle(gl)
  if (!triangle) {
    releaseContext(gl)
    return null
  }
  const floatSupport = probeFloat(gl)
  let current = measureOf(options.host, canvas)
  let alive = true
  let raf = 0
  let last = 0
  let inView = true
  let pageVisible = document.visibilityState !== "hidden"
  let observer: IntersectionObserver | null = null
  const context = gl

  function poke() {
    if (!alive || raf !== 0) return
    if (!shouldDrawFrame(inView, pageVisible)) return
    raf = requestAnimationFrame(tick)
  }

  function tick(now: number) {
    raf = 0
    if (!alive || !shouldDrawFrame(inView, pageVisible)) return
    const dt = last === 0 ? 0 : Math.min(0.05, (now - last) / 1000)
    last = now
    current = measureOf(options.host, canvas)
    options.frame({ gl: context, time: now / 1000, dt, size: current })
    if (alive) poke()
  }

  function onVisibility() {
    pageVisible = document.visibilityState !== "hidden"
    poke()
  }

  if (typeof IntersectionObserver === "function") {
    inView = false
    observer = new IntersectionObserver((entries) => {
      const entry = entries[entries.length - 1]
      inView = entry ? entry.isIntersecting : true
      poke()
    })
    observer.observe(options.host)
  }
  document.addEventListener("visibilitychange", onVisibility)
  poke()

  return {
    gl,
    floatSupport,
    size: () => current,
    createPair: (width, height) => (alive ? createPair(gl, width, height, floatSupport) : null),
    draw() {
      if (!alive) return
      gl.bindBuffer(gl.ARRAY_BUFFER, triangle)
      gl.enableVertexAttribArray(0)
      gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0)
      gl.drawArrays(gl.TRIANGLES, 0, 3)
    },
    dispose() {
      if (!alive) return
      alive = false
      if (raf !== 0) cancelAnimationFrame(raf)
      raf = 0
      observer?.disconnect()
      document.removeEventListener("visibilitychange", onVisibility)
      gl.bindBuffer(gl.ARRAY_BUFFER, null)
      gl.deleteBuffer(triangle)
      releaseContext(gl)
    },
  }
}
